"""components/kpi_cards.py — Composants UI réutilisables."""import streamlit as stfrom config import Cdef kpi_card(title: str, value: str, subtitle: str = "",             color: str = None, icon: str = "") -> None:    accent = C.get(color, color) if color else C["blue"]    st.markdown(f"""    <div style="background:{C['card']};border:1px solid {C['border']};                border-top:3px solid {accent};border-radius:10px;                padding:18px 16px 14px;text-align:center;height:110px;                display:flex;flex-direction:column;justify-content:center;align-items:center;">        <div style="font-size:11px;color:{C['muted']};letter-spacing:0.05em;                    text-transform:uppercase;margin-bottom:6px;">{icon} {title}</div>        <div style="font-size:28px;font-weight:700;color:{accent};                    line-height:1.1;margin-bottom:4px;">{value}</div>        <div style="font-size:11px;color:{C['muted']};">{subtitle}</div>    </div>    """, unsafe_allow_html=True)def kpi_row(cards: list) -> None:    cols = st.columns(len(cards))    for col, card in zip(cols, cards):        with col:            kpi_card(**card)    st.markdown("<div style='margin-bottom:8px'></div>", unsafe_allow_html=True)def mini_badge(label: str, color: str) -> str:    accent = C.get(color, color)    return (        f'<span style="background:{accent}22;color:{accent};border:1px solid {accent}44;'        f'border-radius:4px;padding:2px 8px;font-size:11px;font-weight:600;">{label}</span>'    )def section_title(text: str, emoji: str = "") -> None:    st.markdown(f"""    <div style="margin:28px 0 12px;">        <span style="font-size:17px;font-weight:600;color:{C['text']};">{emoji} {text}</span>        <div style="height:1px;background:{C['border']};margin-top:8px;"></div>    </div>    """, unsafe_allow_html=True)def page_header(title: str, subtitle: str = "", emoji: str = "") -> None:    st.markdown(f"""    <div style="padding:20px 0 16px;border-bottom:1px solid {C['border']};margin-bottom:24px;">        <h1 style="font-size:24px;font-weight:700;color:{C['text']};margin:0 0 4px 0;">            {emoji} {title}        </h1>        <p style="font-size:13px;color:{C['muted']};margin:0;">{subtitle}</p>    </div>    """, unsafe_allow_html=True)